define('availability_workshopattendance/form',['jquery'],function($){var S=[{value:'Booked',label:'Booked \u2014 registered, not yet confirmed'},{value:'Confirmed',label:'Confirmed \u2014 place confirmed by RTO'},{value:'Waitlisted',label:'Waitlisted \u2014 on the waitlist'},{value:'Attended',label:'Attended \u2014 was present at the workshop'},{value:'Cancelled',label:'Cancelled \u2014 booking cancelled'},{value:'No Show',label:'No Show \u2014 did not attend'}];function b(s){return S.map(function(o){return'<option value="'+o.value+'"'+(o.value===s?' selected="selected"':'')+'>'+o.label+'</option>';}).join('');}return{getNode:function(json){var wid=(json&&json.workshopid)?parseInt(json.workshopid,10):0;var st=(json&&json.status)?json.status:'Attended';var $n=$('<span class="availability-workshopattendance d-flex align-items-center flex-wrap gap-2"><label class="mb-0 mr-1">Workshop:</label><select name="workshopid" class="custom-select mr-2" style="max-width:320px"><option value="0">Loading workshops\u2026</option></select><label class="mb-0 mr-1">requires status</label><select name="status" class="custom-select">'+b(st)+'</select></span>');$.ajax({url:M.cfg.wwwroot+'/local/workshops/ajax.php',data:{action:'get_workshops',sesskey:M.cfg.sesskey},dataType:'json',success:function(d){var $s=$n.find('select[name="workshopid"]');if(d.success&&d.workshops&&d.workshops.length){var o='<option value="0">\u2014 Select workshop \u2014</option>';d.workshops.forEach(function(w){var id=parseInt(w.id,10);o+='<option value="'+id+'"'+(id===wid?' selected="selected"':'')+'>'+w.workshopcode+' \u2013 '+w.workshopname+' ['+w.status+']</option>';});$s.html(o);$s.trigger('change');}else{$s.html('<option value="0">No workshops found</option>');}},error:function(){$n.find('select[name="workshopid"]').html('<option value="0">Error loading workshops</option>');}});return $n;},fillValue:function(el,json){if(json.workshopid){$(el).find('select[name="workshopid"]').data('target-id',parseInt(json.workshopid,10)).val(json.workshopid);}if(json.status){$(el).find('select[name="status"]').val(json.status);}},focusAfterAdd:function(node){$(node).find('select[name="workshopid"]').focus();}};});
